package site.kael.conversationcompiler.controller.compiler;
import org.springframework.web.bind.annotation.*; import site.kael.conversationcompiler.domain.compiler.CompileRun; import site.kael.conversationcompiler.service.compiler.CompileRunService; import java.util.List;
@RestController @RequestMapping("/api/v1/conversations/{sessionId}/compile-runs") public class ConversationCompileRunController { private final CompileRunService service; public ConversationCompileRunController(CompileRunService s){service=s;} @GetMapping public List<CompileRun> list(@PathVariable String sessionId,@RequestParam(required=false) String status,@RequestParam(defaultValue="50") int limit,@RequestParam(defaultValue="0") int offset){return service.list(sessionId,status,limit,offset);} @PostMapping public java.util.Map<String,Object> create(@PathVariable String sessionId,@RequestParam(defaultValue="manual") String triggerType){long id=service.create(sessionId,site.kael.conversationcompiler.domain.compiler.CompileTriggerType.valueOf(triggerType));return java.util.Map.of("id",id,"status","pending","sessionId",sessionId);}}
